   if(guide)guide.textContent=`${keys.up.toUpperCase()} / ${keys.left.toUpperCase()} / ${keys.down.toUpperCase()} / ${keys.right.toUpperCase()} move · ${keys.interact.toUpperCase()} interact · ${keys.center.toUpperCase()} recenter · arrows pan. The buttons perform the same actions.`;
   let body='';
   if(stage===0)body='<div class="tutorial-practice-tag">Practice 1 · find, then read</div><h3>A directory is a good first colleague.</h3><p>Move your fellow to the brass directory on the lower plaza. The gold line shows the route your command will follow.</p><div class="tutorial-controls">'+button('walk-directory','Walk to directory',undefined,false,true)+button('read-directory','Read the directory',undefined,!nearby(4,8))+'</div><p class="tutorial-hint">Reaching the sign and reading it are separate actions. Try a ground click or the movement buttons below.</p>';
   if(stage===1)body='<div class="tutorial-practice-tag">Practice 2 · find the office</div><h3>The sign has a useful lead.</h3><p>The practice office is in the north-east courtyard. The old stair shortcut is closed; the level path goes around the garden.</p><p>Try <b>Zoom in or out</b>, then <b>Recenter</b>, and walk to the signed door.</p><ul><li>'+(flags.zoomed?'✓':'○')+' Used zoom</li><li>'+(flags.centered?'✓':'○')+' Recentered the view</li><li>'+(flags.officeReached?'✓':'○')+' Reached the practice office</li></ul><div class="tutorial-controls">'+button('walk-office','Walk to practice office',undefined,false,true)+button('open-office','Enter the practice office',undefined,!nearby(10,4))+'</div>';
