   ctx.font='12px Georgia';ctx.textAlign='center';for(const[x,y,text]of[[3,8.8,'DIRECTORY'],[10,4.9,'PRACTICE OFFICE'],[2.5,5.2,'LIBRARY']]){const p=iso(x,y);ctx.fillStyle='#eee2c3';ctx.fillRect(p.x-65,p.y+4,130,19);ctx.fillStyle='#415344';ctx.fillText(text,p.x,p.y+17);}ctx.restore();
