 function cancelFrame(){if(frameId!==null&&caf)caf(frameId);frameId=null;lastFrame=0;}
 function arrive(){if(nearby(4,8)){flags.directoryReached=true;message=stage===0?'Directory reached. Read it with the button or your interaction key.':'Back at the practice directory.';}if(nearby(10,4)){flags.officeReached=true;message='Office reached. Enter when you have tried zoom and recenter.';}renderUI();}
 function finishPath(){while(path.length)player={...path.shift()};arrive();}
 function schedule(){if(destroyed||hidden||paused||reduced||!path.length||frameId!==null||!raf)return;frameId=raf(frame);}
 function frame(now){frameId=null;if(destroyed||hidden||paused||reduced)return;if(!lastFrame)lastFrame=now;const dt=Math.max(0,Math.min(.05,(now-lastFrame)/1000));lastFrame=now;if(path.length){const next=path[0],dx=next.x-player.x,dy=next.y-player.y,d=Math.hypot(dx,dy),step=dt*5;if(d<=step){player={...next};path.shift();if(!path.length)arrive();}else{player.x+=dx/d*step;player.y+=dy/d*step;}draw();}if(path.length)schedule();else lastFrame=0;}
 function walk(tx,ty){if(stage>1){message='The fellow is taking notes indoors. The tabletop controls are your next step.';renderUI();return;}const next=findPath(tx,ty);if(!next){message='That tile is occupied. Choose open ground or use a labeled route button.';renderUI();return;}path=next;message=paused?'Route planned. Resume practice when you are ready.':'A route is planned. Your fellow is on the way.';renderUI();if(paused)return;if(reduced||!ctx||!raf)finishPath();else if(!path.length)arrive();else schedule();}
