 function action(name,value){if(destroyed)return;
   if(name==='exit'){options.onExit?.();return;}if(name==='continue'){if(stage===5)options.onContinue?.();return;}
   if(name==='pause'){paused=!paused;cancelFrame();message=paused?'Practice paused. There is no timer and no hurry.':'Practice resumed.';renderUI();if(!paused&&path.length){if(reduced||!ctx||!raf)finishPath();else schedule();}return;}
   if(name==='replay'){cancelFrame();stage=0;completed=false;paused=false;player={x:2,y:10};path=[];zoom=1;cam={x:0,y:143};prediction='';limit=false;followup='';Object.keys(flags).forEach(k=>flags[k]=false);message='A fresh practice notebook. Your campaign is still waiting safely outside.';renderUI();return;}
   if(name==='reset-step'){resetCurrent();return;}
   if(name==='zoom-in'||name==='zoom-out'){zoom=Math.max(.65,Math.min(1.55,zoom+(name==='zoom-in'?.12:-.12)));flags.zoomed=true;message='Zoom changes the view, not the route.';renderUI();return;}
   if(name==='center'){cam=iso(player.x,player.y);flags.centered=true;message='The view is centered on your fellow.';renderUI();return;}
   if(name==='pan'){const d={left:[-35,0],right:[35,0],up:[0,-28],down:[0,28]}[value];if(d){cam.x+=d[0];cam.y+=d[1];message='View moved. Recenter brings the fellow back into view.';}renderUI();return;}
   if(name==='move'){const d={up:[0,-1],left:[-1,0],down:[0,1],right:[1,0]}[value];if(d)walk(Math.round(player.x)+d[0],Math.round(player.y)+d[1]);return;}
   if(name==='walk-directory'){walk(4,8);return;}if(name==='walk-office'){walk(10,4);return;}
   if(name==='read-directory'){if(stage!==0||!nearby(4,8)){message='Read the directory when your fellow is beside it.';}else{flags.directoryReached=true;flags.directoryRead=true;stage=1;message='Directory read: the practice office is in the north-east courtyard, beyond the closed stair.';}renderUI();return;}
   if(name==='open-office'){if(stage!==1||!nearby(10,4))message='Find the signed office entrance first.';else if(!flags.zoomed||!flags.centered)message='Before entering, try a zoom button and Recenter. Both work in the real campuses too.';else{flags.officeReached=true;flags.officeOpened=true;stage=2;message='Office found. Finding a contact and solving their research problem are separate tasks.';}renderUI();return;}
   if(name==='predict'&&stage===2&&['higher','same','lower'].includes(value)){prediction=value;message='Prediction recorded. Now collect observations; you can revise your expectations.';}
   if(name==='survey-main'){if(stage!==2||!prediction)message='Make a prediction before surveying.';else{flags.mainSurvey=true;message='Convenient street surveyed: '+data(mainStreet).yes+' of '+mainStreet.length+' households received a notice.';}}
   if(name==='survey-both'){if(stage!==2||!flags.mainSurvey)message='Survey the convenient street first so you have a comparison.';else{flags.bothSurvey=true;const r=data([...mainStreet,...sideStreet]);message='The added street changes the estimate to '+r.yes+'/'+r.total+' = '+Math.round(r.rate*100)+'%. These values are calculated from the invented observation cards.';}}
   if(name==='inspect-limit'){if(stage===2&&flags.bothSurvey){stage=3;message='A useful result includes what it cannot establish.';}else message='Collect both street samples before inspecting the conclusion.';}
   if(name==='connect-evidence'){if(stage!==3||!limit)message='Acknowledge the sample’s limitation before connecting the evidence.';else if(followup!=='sample')message='Choose a follow-up that includes missing residents and can challenge the first estimate. Neither identical streets nor a single cause has been established.';else{flags.evidenceConnected=true;stage=4;message='Practice evidence connected: sampling coverage changed the estimate; a wider study is still needed.';}}
   if(name==='next-campus'){if(stage===4&&flags.evidenceConnected){flags.itineraryReviewed=true;message='Northbridge selected. Review all three stops, then travel the connected route.';}else message='Connect the practice evidence before planning the next visit.';}
   if(name==='travel-route'){if(stage===4&&flags.itineraryReviewed){complete();return;}message='Use the named Next campus button and review the itinerary before travelling.';}
   renderUI();
 }
 function click(event){const b=event.target.closest?.('[data-tutorial-action]');if(!b||b.disabled)return;const name=b.dataset.tutorialAction,value=b.dataset.tutorialValue;action(name,value);if(!destroyed){const same=container.querySelector(`[data-tutorial-action="${name}"]${value===undefined?'':`[data-tutorial-value="${value}"]`}`);if(same&&!same.disabled)same.focus?.();else if(stage<2)canvas?.focus?.();}}
 function change(event){const t=event.target,field=t.dataset?.tutorialField;if(stage!==3||!field)return;if(field==='limit')limit=!!t.checked;if(field==='followup')followup=t.value;renderUI();container.querySelector(`[data-tutorial-field="${field}"]`)?.focus?.();}
 function keydown(event){if(destroyed||hidden||event.key==='Escape'||event.ctrlKey||event.altKey||event.metaKey)return;const target=event.target;if(['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(target?.tagName)||target?.isContentEditable)return;if(event.key===' '){event.preventDefault();action('pause');return;}const key=event.key.toLowerCase(),movement=Object.entries(keys).find(([name,value])=>['up','left','down','right'].includes(name)&&value.toLowerCase()===key);if(movement){event.preventDefault();action('move',movement[0]);}else if(key===keys.interact.toLowerCase()){event.preventDefault();if(stage===0)action('read-directory');else if(stage===1)action('open-office');}else if(key===keys.center.toLowerCase()){event.preventDefault();action('center');}else if(event.key.startsWith('Arrow')){event.preventDefault();action('pan',{ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'}[event.key]);}else if(key==='+'||key==='='){event.preventDefault();action('zoom-in');}else if(key==='-'){event.preventDefault();action('zoom-out');}}
 function pointer(event){if(destroyed||stage>1||!canvas?.getBoundingClientRect)return;const r=canvas.getBoundingClientRect(),px=(event.clientX-r.left)*W/r.width,py=(event.clientY-r.top)*H/r.height,wx=(px-W*.5)/zoom+cam.x,wy=(py-H*.53)/zoom+cam.y-TH/2,x=Math.round(wx/TW+wy/TH),y=Math.round(wy/TH-wx/TW);canvas.focus?.();walk(x,y);}
 function visibility(){hidden=!!doc.hidden;if(hidden)cancelFrame();else{lastFrame=0;if(reduced&&!paused&&path.length)finishPath();else schedule();draw();}}
 container.addEventListener?.('click',click);container.addEventListener?.('change',change);container.addEventListener?.('keydown',keydown);canvas?.addEventListener?.('pointerdown',pointer);doc?.addEventListener?.('visibilitychange',visibility);
 renderUI();if(typeof setTimeout==='function')focusTimer=setTimeout(()=>{if(!destroyed)canvas?.focus?.();},65);
 return{destroy(){if(destroyed)return;destroyed=true;cancelFrame();if(focusTimer!==null)clearTimeout(focusTimer);container.removeEventListener?.('click',click);container.removeEventListener?.('change',change);container.removeEventListener?.('keydown',keydown);canvas?.removeEventListener?.('pointerdown',pointer);doc?.removeEventListener?.('visibilitychange',visibility);},setReduced(value){reduced=!!value;cancelFrame();if(reduced&&!paused&&!hidden&&path.length)finishPath();else schedule();draw();},getState(){return{stage,title:titles[stage],player:{...player},path:path.map(p=>({...p})),flags:{...flags},prediction,limit,followup,complete:completed,notified,destroyed,reduced,hidden,paused,zoom,cam:{...cam},supported:!!ctx};}};
